import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();ws.onmessage=({data})=>{const m=JSON.parse(data);if(pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
try{
 await send('Page.navigate',{url:'http://127.0.0.1:3001/'});await new Promise(r=>setTimeout(r,500));
 const result=await evaluate(`(async()=>{
 const {scheduleSwordSound}=await import('/src/js/toy-room/SwordAudio.js');const {scheduleDamageSound}=await import('/src/js/toy-room/DamageAudio.js');const cases=[];
 for(const event of ['player_attack','sword_impact','sword_block'])for(const volume of [0,.5,1]){
  const ctx=new OfflineAudioContext(1,44100,44100),gain=ctx.createGain();gain.gain.value=volume;gain.connect(ctx.destination);let nodes=0,ended=0;
  scheduleSwordSound(ctx,gain,node=>{nodes++;node.addEventListener('ended',()=>ended++);},event);
  const buffer=await ctx.startRendering(),d=buffer.getChannelData(0);let peak=0,rms=0,tail=0;for(let i=0;i<d.length;i++){peak=Math.max(peak,Math.abs(d[i]));rms+=d[i]*d[i];if(i>22050)tail=Math.max(tail,Math.abs(d[i]));}
  cases.push({event,volume,peak,rms:Math.sqrt(rms/d.length),tail,nodes,ended});
 }
 for(const actor of ['train','robot','dinosaur','bear']){
  const ctx=new OfflineAudioContext(1,44100,44100);scheduleSwordSound(ctx,ctx.destination,()=>{},'sword_impact');scheduleDamageSound(ctx,ctx.destination,()=>{},actor,true);
  const buffer=await ctx.startRendering();let peak=0;for(const v of buffer.getChannelData(0))peak=Math.max(peak,Math.abs(v));cases.push({actor,peak});
 }
 const {createAudioSystem}=await import('/src/js/audio.js');const audio=createAudioSystem();audio.initAudio();const integrated=['player_attack','sword_impact','sword_block'].map(event=>audio.playArenaSound(event));audio.setMasterVolume(.5);audio.setMuted(true);audio.clearActiveSounds();return {cases,integrated};
 })()`);
 for(const c of result.cases){assert.ok(c.peak<.95,'Sinal sem clipping: '+JSON.stringify(c));if(c.event){assert.equal(c.ended,c.nodes,'Todas as vozes encerram');assert.ok(c.tail<.0001);if(c.volume===0)assert.equal(c.peak,0,'Mudo zera saída');else assert.ok(c.peak>.02&&c.rms>.002,'Som audível');}}
 for(const event of ['player_attack','sword_impact','sword_block']){const half=result.cases.find(c=>c.event===event&&c.volume===.5),full=result.cases.find(c=>c.event===event&&c.volume===1);assert.ok(Math.abs(half.rms/full.rms-.5)<1e-6,'Ganho mestre proporcional');}
 assert.ok(result.integrated.every(Boolean),'Eventos públicos agendam os três sons');console.log('APROVADO: 9 renderizações de corte/impacto/bloqueio, mudo, volume proporcional, vozes encerradas e 4 misturas com reação dos inimigos sem clipping.');console.log(JSON.stringify(result));
}finally{ws.close();}
